[CmdletBinding()]
param(
    [switch]$DryRun,
    [switch]$Revert,
    [switch]$Force
)

$ErrorActionPreference = 'Stop'
$Feature = 'options-view-polish'
$RepoRoot = (Get-Location).Path

if (-not (Test-Path -LiteralPath (Join-Path $RepoRoot 'CMakeLists.txt') -PathType Leaf)) {
    throw "FAIL ROOT: Run this script from the Sample Box repository root (CMakeLists.txt was not found)."
}

$Branch = (git -C $RepoRoot branch --show-current 2>$null)
if (($Branch -eq 'main' -or $Branch -eq 'master') -and -not $Force) {
    throw "FAIL BRANCH: Refusing to write on '$Branch'. Switch to a feature branch or pass -Force explicitly."
}

$BackupRoot = Join-Path $RepoRoot ('.git\' + $Feature + '-patch-backup')
$ManifestPath = Join-Path $BackupRoot 'latest-manifest.txt'

if ($Revert) {
    if (-not (Test-Path -LiteralPath $ManifestPath -PathType Leaf)) { throw "FAIL REVERT: No manifest found at $ManifestPath" }
    foreach ($Line in (Get-Content -LiteralPath $ManifestPath)) {
        if ([string]::IsNullOrWhiteSpace($Line)) { continue }
        $Parts = $Line -split '\t', 3
        if ($Parts[0] -ne 'MODIFIED') { throw "FAIL REVERT: Unknown manifest mode '$($Parts[0])'" }
        Copy-Item -LiteralPath $Parts[2] -Destination (Join-Path $RepoRoot $Parts[1]) -Force
        Write-Host "OK REVERT $($Parts[1])"
    }
    exit 0
}

$Timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$ThisBackup = Join-Path $BackupRoot $Timestamp
$Manifest = New-Object System.Collections.Generic.List[string]
$HadFailure = $false

function Write-Replacement {
    param([string]$EditId, [string]$RelativePath, [string]$Base64Content)
    $Target = Join-Path $RepoRoot $RelativePath
    if (-not (Test-Path -LiteralPath $Target -PathType Leaf)) {
        Write-Host "FAIL ${EditId}: Missing expected file $RelativePath" -ForegroundColor Red
        $script:HadFailure = $true
        return
    }
    $NewText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
    $OldBytes = [System.IO.File]::ReadAllBytes($Target)
    $HasBom = $OldBytes.Length -ge 3 -and $OldBytes[0] -eq 0xEF -and $OldBytes[1] -eq 0xBB -and $OldBytes[2] -eq 0xBF
    $OldText = [System.Text.Encoding]::UTF8.GetString($OldBytes)
    if ($HasBom) { $OldText = $OldText.TrimStart([char]0xFEFF) }
    $NormalizedNew = if ($OldText.Contains("`r`n")) { $NewText -replace "`n", "`r`n" } else { $NewText }
    if ($OldText -eq $NormalizedNew) { Write-Host "SKIP ${EditId}: $RelativePath already matches this patch" -ForegroundColor Yellow; return }
    if ($DryRun) { Write-Host "OK DRYRUN ${EditId}: replace $RelativePath"; return }
    $Backup = Join-Path $ThisBackup $RelativePath
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Backup) | Out-Null
    Copy-Item -LiteralPath $Target -Destination $Backup -Force
    $Manifest.Add("MODIFIED`t$RelativePath`t$Backup")
    [System.IO.File]::WriteAllText($Target, $NormalizedNew, (New-Object System.Text.UTF8Encoding($HasBom)))
    Write-Host "OK ${EditId}: replaced $RelativePath" -ForegroundColor Green
}

Write-Replacement -EditId 'E01' -RelativePath 'src/UI/BrowserView.h' -Base64Content ''
Write-Replacement -EditId 'E02' -RelativePath 'src/UI/BrowserView.cpp' -Base64Content ''
Write-Replacement -EditId 'E03' -RelativePath 'src/UI/CoverArtCard.cpp' -Base64Content ''
Write-Replacement -EditId 'E04' -RelativePath 'src/UI/OptionsComponent.cpp' -Base64Content ''

if ($HadFailure) { exit 1 }
if (-not $DryRun -and $Manifest.Count -gt 0) {
    New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
    Set-Content -LiteralPath $ManifestPath -Value $Manifest -Encoding UTF8
    Write-Host "OK MANIFEST: $ManifestPath" -ForegroundColor Green
}
Write-Host 'OK COMPLETE: Options view polish patch finished.' -ForegroundColor Green

